// computeDtbs request carries: the document transfer and the attribute lists.
package v1

import (
	"encoding/json"
	"reflect"
	"testing"
	"time"
)

func roundTrip[T any](t *testing.T, in T) T {
	t.Helper()
	b, e := json.Marshal(in)
	if e != nil {
		t.Fatal(e)
	}
	var out T
	if e = json.Unmarshal(b, &out); e != nil {
		t.Fatalf("%s: %v", b, e)
	}
	return out
}

func mustMarshal(t *testing.T, v any) string {
	t.Helper()
	b, e := json.Marshal(v)
	if e != nil {
		t.Fatal(e)
	}
	return string(b)
}

func TestComputeDtbsRequestRoundTrip(t *testing.T) {
	attr := NewRequestAttributeV3("d0235059-d463-4937-a2aa-20efdd000001", "hashAlgorithm", ATTRIBUTECONTENTTYPE_STRING, ATTRIBUTEVERSION_V3)
	attr.Content = []BaseAttributeContentDtoV3{StringAttributeContentV3AsBaseAttributeContentDtoV3(NewStringAttributeContentV3("SHA-256", ATTRIBUTECONTENTTYPE_STRING))}
	attrs := []RequestAttribute{RequestAttributeV3AsRequestAttribute(attr)}
	signingTime := time.Date(2026, 11, 24, 12, 0, 0, 0, time.UTC)

	documents := map[string]DocumentTransfer{
		"inline":     InlineDocumentTransferAsDocumentTransfer(NewInlineDocumentTransfer("aGk=", DOCUMENTTRANSFERMODE_INLINE)),
		"digestOnly": DigestOnlyDocumentTransferAsDocumentTransfer(NewDigestOnlyDocumentTransfer(sha256Digest, DIGESTALGORITHM_SHA_256, DOCUMENTTRANSFERMODE_DIGEST_ONLY)),
	}
	for name, doc := range documents {
		t.Run(name, func(t *testing.T) {
			in := *NewComputeDtbsRequest("mrtd-sod", attrs, doc, []string{"Y2VydA=="}, signingTime, SIGNATUREALGORITHM_SHA256WITH_RSA, []RequestAttribute{})
			got := roundTrip(t, in)
			if (got.Document.InlineDocumentTransfer == nil) != (in.Document.InlineDocumentTransfer == nil) {
				t.Fatalf("variant: got %+v, want %+v", got.Document, in.Document)
			}
			if g, w := mustMarshal(t, got.Document), mustMarshal(t, in.Document); g != w {
				t.Fatalf("document: got %s, want %s", g, w)
			}
			if len(got.FormattingAttributes) != 1 || got.FormattingAttributes[0].RequestAttributeV3 == nil {
				t.Fatalf("formatting attributes: %+v", got.FormattingAttributes)
			}
			if s := got.FormattingAttributes[0].RequestAttributeV3.Content[0].StringAttributeContentV3; s == nil || s.Data != "SHA-256" {
				t.Fatalf("attribute content: %+v", got.FormattingAttributes[0].RequestAttributeV3.Content[0])
			}
			if !got.SigningTime.Equal(signingTime) || got.SignatureAlgorithm != SIGNATUREALGORITHM_SHA256WITH_RSA {
				t.Fatalf("scalars: %+v", got)
			}
			if !reflect.DeepEqual(roundTrip(t, got), got) {
				t.Fatal("a second round trip changed the request")
			}
		})
	}
}
